## protos/user_service/service.proto

```protobuf
syntax = "proto3";

package user_service;

import "common/types.proto";

option go_package = "github.com/ecommerce/user_service";

// User message
message User {
    string id = 1;
    string name = 2;
    string email = 3;
    string status = 4;
    map<string, string> metadata = 5;
    common.Timestamp created_at = 6;
    common.Timestamp updated_at = 7;
}

// Request/Response messages
message CreateUserRequest {
    string name = 1;
    string email = 2;
    map<string, string> metadata = 3;
}

message CreateUserResponse {
    User user = 1;
}

message GetUserRequest {
    string id = 1;
}

message GetUserResponse {
    User user = 1;
}

message ListUsersRequest {
    common.PaginationRequest pagination = 1;
    string status = 2;
    string search = 3;
}

message ListUsersResponse {
    repeated User users = 1;
    common.PaginationResponse pagination = 2;
}

message UpdateUserRequest {
    string id = 1;
    optional string name = 2;
    optional string email = 3;
    optional string status = 4;
    map<string, string> metadata = 5;
}

message UpdateUserResponse {
    User user = 1;
}

message DeleteUserRequest {
    string id = 1;
}

message DeleteUserResponse {
    bool success = 1;
}

// Streaming messages
message UserEvent {
    string event_type = 1;  // created, updated, deleted
    User user = 2;
    common.Timestamp timestamp = 3;
}

// Service definition
service UserServiceService {
    // Unary RPCs
    rpc CreateUser(CreateUserRequest) returns (CreateUserResponse);
    rpc GetUser(GetUserRequest) returns (GetUserResponse);
    rpc UpdateUser(UpdateUserRequest) returns (UpdateUserResponse);
    rpc DeleteUser(DeleteUserRequest) returns (DeleteUserResponse);
    rpc ListUsers(ListUsersRequest) returns (ListUsersResponse);

    // Server streaming RPC
    rpc WatchUsers(common.Empty) returns (stream UserEvent);

    // Bidirectional streaming RPC
    rpc BulkUserOperations(stream CreateUserRequest) returns (stream CreateUserResponse);
}
```

## user-service/server.py

```python
import asyncio
import logging
from concurrent import futures
import grpc
from grpc_reflection.v1alpha import reflection
from grpc_health.v1 import health_pb2, health_pb2_grpc
from grpc_health.v1.health import HealthServicer
from opentelemetry import trace
from opentelemetry.instrumentation.grpc import GrpcInstrumentorServer
from prometheus_client import start_http_server, Counter, Histogram

from generated import user_service_pb2
from generated import user_service_pb2_grpc
from service import UserServiceServicer
from interceptors import LoggingInterceptor, AuthInterceptor, RateLimitInterceptor

# Metrics
REQUEST_COUNT = Counter(
    'user_service_requests_total',
    'Total requests',
    ['method', 'status']
)
REQUEST_LATENCY = Histogram(
    'user_service_request_latency_seconds',
    'Request latency',
    ['method']
)

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)


async def serve():
    # Start metrics server
    start_http_server(8001)

    # Create server with interceptors
    server = grpc.aio.server(
        futures.ThreadPoolExecutor(max_workers=10),
        interceptors=[
            LoggingInterceptor(),
            AuthInterceptor(),
            RateLimitInterceptor(rate=100, per_seconds=1),
        ],
        options=[
            ('grpc.max_send_message_length', 50 * 1024 * 1024),
            ('grpc.max_receive_message_length', 50 * 1024 * 1024),
            ('grpc.keepalive_time_ms', 10000),
            ('grpc.keepalive_timeout_ms', 5000),
            ('grpc.keepalive_permit_without_calls', True),
            ('grpc.http2.max_pings_without_data', 0),
            ('grpc.http2.min_time_between_pings_ms', 10000),
            ('grpc.http2.min_ping_interval_without_data_ms', 5000),
        ],
    )

    # Add services
    user_service_pb2_grpc.add_UserServiceServiceServicer_to_server(
        UserServiceServicer(), server
    )

    # Add health check service
    health_servicer = HealthServicer()
    health_pb2_grpc.add_HealthServicer_to_server(health_servicer, server)
    health_servicer.set(
        "user_service.UserServiceService",
        health_pb2.HealthCheckResponse.SERVING
    )

    # Add reflection for debugging
    SERVICE_NAMES = (
        user_service_pb2.DESCRIPTOR.services_by_name['UserServiceService'].full_name,
        reflection.SERVICE_NAME,
    )
    reflection.enable_server_reflection(SERVICE_NAMES, server)

    # Instrument with OpenTelemetry
    GrpcInstrumentorServer().instrument()

    # Start server
    listen_addr = '[::]:50051'
    server.add_insecure_port(listen_addr)
    logger.info(f"Starting gRPC server on {listen_addr}")

    await server.start()

    # Graceful shutdown
    async def graceful_shutdown():
        logger.info("Shutting down gracefully...")
        await server.stop(5)

    try:
        await server.wait_for_termination()
    except KeyboardInterrupt:
        await graceful_shutdown()


if __name__ == '__main__':
    asyncio.run(serve())
```

## user-service/service.py

```python
import uuid
from datetime import datetime
from typing import AsyncIterator
import grpc
import asyncio
from sqlalchemy.ext.asyncio import AsyncSession

from generated import user_service_pb2
from generated import user_service_pb2_grpc
from generated import common_pb2
from database import get_session
from models import UserModel
from events import publish_event


class UserServiceServicer(user_service_pb2_grpc.UserServiceServiceServicer):

    async def CreateUser(
        self,
        request: user_service_pb2.CreateUserRequest,
        context: grpc.aio.ServicerContext,
    ) -> user_service_pb2.CreateUserResponse:
        async with get_session() as session:
            # Create entity
            user = UserModel(
                id=str(uuid.uuid4()),
                name=request.name,
                email=request.email,
                metadata=dict(request.metadata),
                status="active",
            )
            session.add(user)
            await session.commit()
            await session.refresh(user)

            # Publish event
            await publish_event(
                event_type="UserCreated",
                data={user.to_dict()},
            )

            return user_service_pb2.CreateUserResponse(
                user=self._to_proto(user)
            )

    async def GetUser(
        self,
        request: user_service_pb2.GetUserRequest,
        context: grpc.aio.ServicerContext,
    ) -> user_service_pb2.GetUserResponse:
        async with get_session() as session:
            user = await session.get(UserModel, request.id)

            if not user:
                context.set_code(grpc.StatusCode.NOT_FOUND)
                context.set_details(f"User not found: {request.id}")
                return user_service_pb2.GetUserResponse()

            return user_service_pb2.GetUserResponse(
                user=self._to_proto(user)
            )

    async def ListUsers(
        self,
        request: user_service_pb2.ListUsersRequest,
        context: grpc.aio.ServicerContext,
    ) -> user_service_pb2.ListUsersResponse:
        async with get_session() as session:
            page = request.pagination.page or 1
            page_size = request.pagination.page_size or 20

            # Query with filters
            query = session.query(UserModel)

            if request.status:
                query = query.filter(UserModel.status == request.status)

            if request.search:
                query = query.filter(
                    UserModel.name.ilike(f"%{request.search}%")
                )

            # Count total
            total = await session.execute(query.count())

            # Paginate
            users = await session.execute(
                query.offset((page - 1) * page_size).limit(page_size)
            )

            return user_service_pb2.ListUsersResponse(
                users=[self._to_proto(u) for u in users.scalars()],
                pagination=common_pb2.PaginationResponse(
                    total=total,
                    page=page,
                    page_size=page_size,
                    total_pages=(total + page_size - 1) // page_size,
                ),
            )

    async def WatchUsers(
        self,
        request: common_pb2.Empty,
        context: grpc.aio.ServicerContext,
    ) -> AsyncIterator[user_service_pb2.UserEvent]:
        """Server streaming - watch for user changes"""
        # Subscribe to Redis pub/sub or message queue
        from events import subscribe_events

        async for event in subscribe_events("User*"):
            if context.cancelled():
                break

            yield user_service_pb2.UserEvent(
                event_type=event["type"],
                user=self._to_proto(event["data"]),
                timestamp=common_pb2.Timestamp(
                    seconds=int(datetime.now().timestamp())
                ),
            )

    async def BulkUserOperations(
        self,
        request_iterator: AsyncIterator[user_service_pb2.CreateUserRequest],
        context: grpc.aio.ServicerContext,
    ) -> AsyncIterator[user_service_pb2.CreateUserResponse]:
        """Bidirectional streaming - bulk create users"""
        async for request in request_iterator:
            response = await self.CreateUser(request, context)
            yield response

    def _to_proto(self, model: UserModel) -> user_service_pb2.User:
        return user_service_pb2.User(
            id=model.id,
            name=model.name,
            email=model.email,
            status=model.status,
            metadata=model.metadata or {},
            created_at=common_pb2.Timestamp(
                seconds=int(model.created_at.timestamp())
            ),
            updated_at=common_pb2.Timestamp(
                seconds=int(model.updated_at.timestamp())
            ) if model.updated_at else None,
        )
```

## user-service/client.py (gRPC Client)

```python
import grpc
from grpc import aio
import asyncio
from typing import List, AsyncIterator

from generated import user_service_pb2
from generated import user_service_pb2_grpc
from generated import common_pb2


class UserServiceClient:
    def __init__(self, host: str = "localhost", port: int = 50051):
        self.channel = None
        self.stub = None
        self.host = host
        self.port = port

    async def connect(self):
        self.channel = aio.insecure_channel(
            f"{self.host}:{self.port}",
            options=[
                ('grpc.keepalive_time_ms', 10000),
                ('grpc.keepalive_timeout_ms', 5000),
            ],
        )
        self.stub = user_service_pb2_grpc.UserServiceServiceStub(self.channel)

    async def close(self):
        if self.channel:
            await self.channel.close()

    async def create_user(
        self,
        name: str,
        email: str,
        metadata: dict = None,
    ) -> user_service_pb2.User:
        request = user_service_pb2.CreateUserRequest(
            name=name,
            email=email,
            metadata=metadata or {},
        )
        response = await self.stub.CreateUser(request)
        return response.user

    async def get_user(self, id: str) -> user_service_pb2.User:
        request = user_service_pb2.GetUserRequest(id=id)
        response = await self.stub.GetUser(request)
        return response.user

    async def list_users(
        self,
        page: int = 1,
        page_size: int = 20,
        status: str = None,
        search: str = None,
    ) -> List[user_service_pb2.User]:
        request = user_service_pb2.ListUsersRequest(
            pagination=common_pb2.PaginationRequest(
                page=page,
                page_size=page_size,
            ),
            status=status or "",
            search=search or "",
        )
        response = await self.stub.ListUsers(request)
        return list(response.users)

    async def watch_users(self) -> AsyncIterator[user_service_pb2.UserEvent]:
        request = common_pb2.Empty()
        async for event in self.stub.WatchUsers(request):
            yield event

    async def bulk_create_users(
        self,
        items: List[dict],
    ) -> List[user_service_pb2.User]:
        async def request_generator():
            for item in items:
                yield user_service_pb2.CreateUserRequest(
                    name=item["name"],
                    email=item["email"],
                    metadata=item.get("metadata", {}),
                )

        results = []
        async for response in self.stub.BulkUserOperations(request_generator()):
            results.append(response.user)
        return results


# Usage example
async def main():
    client = UserServiceClient()
    await client.connect()

    try:
        # Create
        user = await client.create_user(
            name="John Doe",
            email="john@example.com",
        )
        print(f"Created: {user.id}")

        # Get
        user = await client.get_user(user.id)
        print(f"Got: {user.name}")

        # List
        users = await client.list_users(page=1, page_size=10)
        print(f"Total: {len(users)}")

        # Watch (streaming)
        async for event in client.watch_users():
            print(f"Event: {event.event_type} - {event.user.id}")
            break  # Stop after first event

    finally:
        await client.close()


if __name__ == "__main__":
    asyncio.run(main())
```

## docker-compose.yml

```yaml
version: '3.8'

services:
  user-service:
    build: ./user-service
    ports:
      - "50051:50051"
      - "8001:8001"  # Metrics
    environment:
      - DATABASE_URL=postgresql://admin:password@postgres:5432/user_service_db
      - RABBITMQ_URL=amqp://admin:password@rabbitmq:5672
    depends_on:
      - postgres
      - rabbitmq
    networks:
      - grpc-network

  product-service:
    build: ./product-service
    ports:
      - "50052:50051"
    environment:
      - DATABASE_URL=postgresql://admin:password@postgres:5432/product_service_db
      - USER_SERVICE_GRPC_HOST=user-service
      - USER_SERVICE_GRPC_PORT=50051
    depends_on:
      - user-service
    networks:
      - grpc-network

  postgres:
    image: postgres:15
    environment:
      POSTGRES_USER: admin
      POSTGRES_PASSWORD: password
    volumes:
      - postgres_data:/var/lib/postgresql/data
    networks:
      - grpc-network

  rabbitmq:
    image: rabbitmq:3-management
    ports:
      - "15672:15672"
    networks:
      - grpc-network

networks:
  grpc-network:
    driver: bridge

volumes:
  postgres_data:
```

This gRPC microservices setup includes:
- **Protocol Buffers** definitions with common types
- **Unary RPCs** for CRUD operations
- **Server streaming** for real-time updates
- **Bidirectional streaming** for bulk operations
- **Health checks** and **reflection** for debugging
- **Interceptors** for logging, auth, and rate limiting
- **OpenTelemetry** instrumentation
- **Prometheus** metrics
- **Async Python** implementation with SQLAlchemy

