class PatientServiceServicer(patient_service_pb2_grpc.PatientServiceServiceServicer):

    async def CreatePatient(
        self,
        request: patient_service_pb2.CreatePatientRequest,
        context: grpc.aio.ServicerContext,
    ) -> patient_service_pb2.CreatePatientResponse:
