                context.set_details(f"Patient not found: {request.id}")
                return patient_service_pb2.GetPatientResponse()

            return patient_service_pb2.GetPatientResponse(
                patient=self._to_proto(patient)
            )

    async def ListPatients(
        self,
        request: patient_service_pb2.ListPatientsRequest,
