                query.offset((page - 1) * page_size).limit(page_size)
            )

            return patient_service_pb2.ListPatientsResponse(
                patients=[self._to_proto(u) for u in patients.scalars()],
                pagination=common_pb2.PaginationResponse(
                    total=total,
                    page=page,
                    page_size=page_size,
                    total_pages=(total + page_size - 1) // page_size,
                ),
            )

    async def WatchPatients(
        self,
        request: common_pb2.Empty,
        context: grpc.aio.ServicerContext,
    ) -> AsyncIterator[patient_service_pb2.PatientEvent]:
        """Server streaming - watch for patient changes"""
        # Subscribe to Redis pub/sub or message queue
        from events import subscribe_events

        async for event in subscribe_events("Patient*"):
            if context.cancelled():
                break

            yield patient_service_pb2.PatientEvent(
                event_type=event["type"],
                patient=self._to_proto(event["data"]),
                timestamp=common_pb2.Timestamp(
                    seconds=int(datetime.now().timestamp())
                ),
            )

    async def BulkPatientOperations(
        self,
        request_iterator: AsyncIterator[patient_service_pb2.CreatePatientRequest],
        context: grpc.aio.ServicerContext,
    ) -> AsyncIterator[patient_service_pb2.CreatePatientResponse]:
        """Bidirectional streaming - bulk create patients"""
        async for request in request_iterator:
            response = await self.CreatePatient(request, context)
            yield response

    def _to_proto(self, model: PatientModel) -> patient_service_pb2.Patient:
        return patient_service_pb2.Patient(
            id=model.id,
            name=model.name,
            email=model.email,
            status=model.status,
            metadata=model.metadata or {},
            created_at=common_pb2.Timestamp(
                seconds=int(model.created_at.timestamp())
            ),
            updated_at=common_pb2.Timestamp(
                seconds=int(model.updated_at.timestamp())
            ) if model.updated_at else None,
        )
