    string id = 1;
    string name = 2;
    string email = 3;
    string status = 4;
    map<string, string> metadata = 5;
    common.Timestamp created_at = 6;
    common.Timestamp updated_at = 7;
}

// Request/Response messages
message CreateAccountRequest {
    string name = 1;
    string email = 2;
    map<string, string> metadata = 3;
}

message CreateAccountResponse {
    Account account = 1;
}

message GetAccountRequest {
    string id = 1;
}

message GetAccountResponse {
    Account account = 1;
}

message ListAccountsRequest {
    common.PaginationRequest pagination = 1;
    string status = 2;
    string search = 3;
}

message ListAccountsResponse {
    repeated Account accounts = 1;
    common.PaginationResponse pagination = 2;
}

message UpdateAccountRequest {
    string id = 1;
    optional string name = 2;
    optional string email = 3;
    optional string status = 4;
    map<string, string> metadata = 5;
}

message UpdateAccountResponse {
    Account account = 1;
}

message DeleteAccountRequest {
    string id = 1;
}

message DeleteAccountResponse {
    bool success = 1;
}

// Streaming messages
message AccountEvent {
    string event_type = 1;  // created, updated, deleted
    Account account = 2;
    common.Timestamp timestamp = 3;
}

// Service definition
service AccountServiceService {
    // Unary RPCs
    rpc CreateAccount(CreateAccountRequest) returns (CreateAccountResponse);
    rpc GetAccount(GetAccountRequest) returns (GetAccountResponse);
    rpc UpdateAccount(UpdateAccountRequest) returns (UpdateAccountResponse);
    rpc DeleteAccount(DeleteAccountRequest) returns (DeleteAccountResponse);
    rpc ListAccounts(ListAccountsRequest) returns (ListAccountsResponse);

    // Server streaming RPC
    rpc WatchAccounts(common.Empty) returns (stream AccountEvent);

    // Bidirectional streaming RPC
    rpc BulkAccountOperations(stream CreateAccountRequest) returns (stream CreateAccountResponse);
}
