```python
import uuid
from datetime import datetime
from typing import AsyncIterator
import grpc
import asyncio
from sqlalchemy.ext.asyncio import AsyncSession

from generated import account_service_pb2
from generated import account_service_pb2_grpc
from generated import common_pb2
from database import get_session
from models import AccountModel
from events import publish_event


class AccountServiceServicer(account_service_pb2_grpc.AccountServiceServiceServicer):

    async def CreateAccount(
        self,
        request: account_service_pb2.CreateAccountRequest,
        context: grpc.aio.ServicerContext,
    ) -> account_service_pb2.CreateAccountResponse:
        async with get_session() as session:
            # Create entity
            account = AccountModel(
                id=str(uuid.uuid4()),
                name=request.name,
                email=request.email,
                metadata=dict(request.metadata),
                status="active",
            )
            session.add(account)
            await session.commit()
            await session.refresh(account)

            # Publish event
            await publish_event(
                event_type="AccountCreated",
                data={account.to_dict()},
            )

            return account_service_pb2.CreateAccountResponse(
                account=self._to_proto(account)
            )

    async def GetAccount(
        self,
        request: account_service_pb2.GetAccountRequest,
        context: grpc.aio.ServicerContext,
    ) -> account_service_pb2.GetAccountResponse:
        async with get_session() as session:
            account = await session.get(AccountModel, request.id)

            if not account:
                context.set_code(grpc.StatusCode.NOT_FOUND)
                context.set_details(f"Account not found: {request.id}")
                return account_service_pb2.GetAccountResponse()

            return account_service_pb2.GetAccountResponse(
                account=self._to_proto(account)
            )

    async def ListAccounts(
        self,
        request: account_service_pb2.ListAccountsRequest,
        context: grpc.aio.ServicerContext,
    ) -> account_service_pb2.ListAccountsResponse:
        async with get_session() as session:
            page = request.pagination.page or 1
            page_size = request.pagination.page_size or 20

            # Query with filters
            query = session.query(AccountModel)

            if request.status:
                query = query.filter(AccountModel.status == request.status)

            if request.search:
                query = query.filter(
                    AccountModel.name.ilike(f"%{request.search}%")
                )

            # Count total
            total = await session.execute(query.count())

            # Paginate
            accounts = await session.execute(
                query.offset((page - 1) * page_size).limit(page_size)
            )

            return account_service_pb2.ListAccountsResponse(
                accounts=[self._to_proto(u) for u in accounts.scalars()],
                pagination=common_pb2.PaginationResponse(
                    total=total,
                    page=page,
                    page_size=page_size,
                    total_pages=(total + page_size - 1) // page_size,
                ),
            )

    async def WatchAccounts(
        self,
        request: common_pb2.Empty,
        context: grpc.aio.ServicerContext,
    ) -> AsyncIterator[account_service_pb2.AccountEvent]:
        """Server streaming - watch for account changes"""
        # Subscribe to Redis pub/sub or message queue
        from events import subscribe_events

        async for event in subscribe_events("Account*"):
            if context.cancelled():
                break

            yield account_service_pb2.AccountEvent(
                event_type=event["type"],
                account=self._to_proto(event["data"]),
                timestamp=common_pb2.Timestamp(
                    seconds=int(datetime.now().timestamp())
                ),
            )

    async def BulkAccountOperations(
        self,
        request_iterator: AsyncIterator[account_service_pb2.CreateAccountRequest],
        context: grpc.aio.ServicerContext,
    ) -> AsyncIterator[account_service_pb2.CreateAccountResponse]:
        """Bidirectional streaming - bulk create accounts"""
        async for request in request_iterator:
            response = await self.CreateAccount(request, context)
            yield response

    def _to_proto(self, model: AccountModel) -> account_service_pb2.Account:
        return account_service_pb2.Account(
            id=model.id,
            name=model.name,
            email=model.email,
            status=model.status,
            metadata=model.metadata or {},
            created_at=common_pb2.Timestamp(
                seconds=int(model.created_at.timestamp())
            ),
            updated_at=common_pb2.Timestamp(
                seconds=int(model.updated_at.timestamp())
            ) if model.updated_at else None,
        )
