import uuid
from datetime import datetime
from typing import AsyncIterator
import grpc
import asyncio
from sqlalchemy.ext.asyncio import AsyncSession

from generated import shipment_service_pb2
from generated import shipment_service_pb2_grpc
from generated import common_pb2
from database import get_session
from models import ShipmentModel
from events import publish_event


class ShipmentServiceServicer(shipment_service_pb2_grpc.ShipmentServiceServiceServicer):

    async def CreateShipment(
        self,
        request: shipment_service_pb2.CreateShipmentRequest,
        context: grpc.aio.ServicerContext,
    ) -> shipment_service_pb2.CreateShipmentResponse:
        async with get_session() as session:
            # Create entity
            shipment = ShipmentModel(
                id=str(uuid.uuid4()),
                name=request.name,
                email=request.email,
                metadata=dict(request.metadata),
                status="active",
            )
            session.add(shipment)
            await session.commit()
            await session.refresh(shipment)

            # Publish event
            await publish_event(
                event_type="ShipmentCreated",
                data={shipment.to_dict()},
            )

            return shipment_service_pb2.CreateShipmentResponse(
                shipment=self._to_proto(shipment)
            )

    async def GetShipment(
        self,
        request: shipment_service_pb2.GetShipmentRequest,
        context: grpc.aio.ServicerContext,
    ) -> shipment_service_pb2.GetShipmentResponse:
        async with get_session() as session:
            shipment = await session.get(ShipmentModel, request.id)

            if not shipment:
                context.set_code(grpc.StatusCode.NOT_FOUND)
                context.set_details(f"Shipment not found: {request.id}")
                return shipment_service_pb2.GetShipmentResponse()

            return shipment_service_pb2.GetShipmentResponse(
                shipment=self._to_proto(shipment)
            )

    async def ListShipments(
        self,
        request: shipment_service_pb2.ListShipmentsRequest,
        context: grpc.aio.ServicerContext,
    ) -> shipment_service_pb2.ListShipmentsResponse:
        async with get_session() as session:
            page = request.pagination.page or 1
            page_size = request.pagination.page_size or 20

            # Query with filters
            query = session.query(ShipmentModel)

            if request.status:
                query = query.filter(ShipmentModel.status == request.status)

            if request.search:
                query = query.filter(
                    ShipmentModel.name.ilike(f"%{request.search}%")
                )

            # Count total
            total = await session.execute(query.count())

            # Paginate
            shipments = await session.execute(
                query.offset((page - 1) * page_size).limit(page_size)
            )

            return shipment_service_pb2.ListShipmentsResponse(
                shipments=[self._to_proto(u) for u in shipments.scalars()],
                pagination=common_pb2.PaginationResponse(
                    total=total,
                    page=page,
                    page_size=page_size,
                    total_pages=(total + page_size - 1) // page_size,
                ),
            )

    async def WatchShipments(
        self,
        request: common_pb2.Empty,
        context: grpc.aio.ServicerContext,
    ) -> AsyncIterator[shipment_service_pb2.ShipmentEvent]:
        """Server streaming - watch for shipment changes"""
        # Subscribe to Redis pub/sub or message queue
        from events import subscribe_events

        async for event in subscribe_events("Shipment*"):
            if context.cancelled():
                break

            yield shipment_service_pb2.ShipmentEvent(
                event_type=event["type"],
                shipment=self._to_proto(event["data"]),
                timestamp=common_pb2.Timestamp(
                    seconds=int(datetime.now().timestamp())
                ),
            )

    async def BulkShipmentOperations(
        self,
        request_iterator: AsyncIterator[shipment_service_pb2.CreateShipmentRequest],
        context: grpc.aio.ServicerContext,
    ) -> AsyncIterator[shipment_service_pb2.CreateShipmentResponse]:
        """Bidirectional streaming - bulk create shipments"""
        async for request in request_iterator:
            response = await self.CreateShipment(request, context)
            yield response

    def _to_proto(self, model: ShipmentModel) -> shipment_service_pb2.Shipment:
        return shipment_service_pb2.Shipment(
            id=model.id,
            name=model.name,
            email=model.email,
            status=model.status,
            metadata=model.metadata or {},
            created_at=common_pb2.Timestamp(
                seconds=int(model.created_at.timestamp())
            ),
            updated_at=common_pb2.Timestamp(
                seconds=int(model.updated_at.timestamp())
            ) if model.updated_at else None,
        )
