import grpc
from grpc import aio
import asyncio
from typing import List, AsyncIterator

from generated import shipment_service_pb2
from generated import shipment_service_pb2_grpc
from generated import common_pb2


class ShipmentServiceClient:
    def __init__(self, host: str = "localhost", port: int = 50051):
        self.channel = None
        self.stub = None
        self.host = host
        self.port = port

    async def connect(self):
        self.channel = aio.insecure_channel(
            f"{self.host}:{self.port}",
            options=[
                ('grpc.keepalive_time_ms', 10000),
                ('grpc.keepalive_timeout_ms', 5000),
            ],
        )
        self.stub = shipment_service_pb2_grpc.ShipmentServiceServiceStub(self.channel)

    async def close(self):
        if self.channel:
            await self.channel.close()

    async def create_shipment(
        self,
        name: str,
        email: str,
        metadata: dict = None,
    ) -> shipment_service_pb2.Shipment:
        request = shipment_service_pb2.CreateShipmentRequest(
            name=name,
            email=email,
            metadata=metadata or {},
        )
        response = await self.stub.CreateShipment(request)
        return response.shipment

    async def get_shipment(self, id: str) -> shipment_service_pb2.Shipment:
        request = shipment_service_pb2.GetShipmentRequest(id=id)
        response = await self.stub.GetShipment(request)
        return response.shipment

    async def list_shipments(
        self,
        page: int = 1,
        page_size: int = 20,
        status: str = None,
        search: str = None,
    ) -> List[shipment_service_pb2.Shipment]:
        request = shipment_service_pb2.ListShipmentsRequest(
            pagination=common_pb2.PaginationRequest(
                page=page,
                page_size=page_size,
            ),
            status=status or "",
            search=search or "",
        )
        response = await self.stub.ListShipments(request)
        return list(response.shipments)

    async def watch_shipments(self) -> AsyncIterator[shipment_service_pb2.ShipmentEvent]:
        request = common_pb2.Empty()
        async for event in self.stub.WatchShipments(request):
            yield event

    async def bulk_create_shipments(
        self,
        items: List[dict],
    ) -> List[shipment_service_pb2.Shipment]:
        async def request_generator():
            for item in items:
                yield shipment_service_pb2.CreateShipmentRequest(
                    name=item["name"],
                    email=item["email"],
                    metadata=item.get("metadata", {}),
                )

        results = []
        async for response in self.stub.BulkShipmentOperations(request_generator()):
            results.append(response.shipment)
        return results


# Usage example
async def main():
    client = ShipmentServiceClient()
    await client.connect()

    try:
        # Create
        shipment = await client.create_shipment(
            name="John Doe",
            email="john@example.com",
        )
        print(f"Created: {shipment.id}")

        # Get
        shipment = await client.get_shipment(shipment.id)
        print(f"Got: {shipment.name}")

        # List
        shipments = await client.list_shipments(page=1, page_size=10)
        print(f"Total: {len(shipments)}")

        # Watch (streaming)
        async for event in client.watch_shipments():
            print(f"Event: {event.event_type} - {event.shipment.id}")
            break  # Stop after first event

    finally:
        await client.close()


if __name__ == "__main__":
    asyncio.run(main())
