version: '3.8'

services:
  user-service:
    build: ./user-service
    ports:
      - "50051:50051"
      - "8001:8001"  # Metrics
    environment:
      - DATABASE_URL=postgresql://admin:password@postgres:5432/user_service_db
      - RABBITMQ_URL=amqp://admin:password@rabbitmq:5672
    depends_on:
      - postgres
      - rabbitmq
    networks:
      - grpc-network

  post-service:
    build: ./post-service
    ports:
      - "50052:50051"
    environment:
      - DATABASE_URL=postgresql://admin:password@postgres:5432/post_service_db
      - USER_SERVICE_GRPC_HOST=user-service
      - USER_SERVICE_GRPC_PORT=50051
    depends_on:
      - user-service
    networks:
      - grpc-network

  postgres:
    image: postgres:15
    environment:
      POSTGRES_USER: admin
      POSTGRES_PASSWORD: password
    volumes:
      - postgres_data:/var/lib/postgresql/data
    networks:
      - grpc-network

  rabbitmq:
